parameters.functionCode:
// Build email content based on reject type
const data = $input.item.json.body || $input.item.json;
const applicationId = data.applicationId;
const candidateEmail = data.candidateEmail || '';
const candidateName = data.candidateName || 'bạn';
const jobTitle = data.jobTitle || 'vị trí ứng tuyển';
const type = data.type || 'cv_match';
const score = data.score != null ? data.score : null;
const reason = data.reason || 'Hồ sơ chưa phù hợp với yêu cầu công việc';

let subject = `[JobMatch] Thông báo kết quả ứng tuyển - ${jobTitle}`;
let body = '';

if (type === 'ai_test') {
  subject = `[JobMatch] Kết quả bài kiểm tra đánh giá năng lực - ${jobTitle}`;
  body = `Xin chào ${candidateName},

Cảm ơn bạn đã dành thời gian hoàn thành bài kiểm tra đánh giá năng lực cho vị trí ${jobTitle} tại công ty chúng tôi.

Sau khi tổng hợp kết quả làm bài của bạn${score != null ? ` (Điểm đạt được: ${score}%)` : ''}, chúng tôi rất tiếc phải thông báo kết quả này chưa đạt mức điểm yêu cầu tối thiểu theo tiêu chuẩn đánh giá của vòng kiểm tra năng lực.

Vì vậy, chúng tôi chưa thể tiếp tục quy trình tuyển dụng với bạn cho vị trí này. Tuy nhiên, thông tin hồ sơ của bạn vẫn sẽ được lưu trữ trong hệ thống và chúng tôi sẽ chủ động liên hệ khi có cơ hội việc làm khác phù hợp hơn.

Chúc bạn luôn gặt hái nhiều thành công trên con đường sự nghiệp!

Trân trọng,
Đội ngũ Tuyển dụng JobMatch VN`;
} else if (type === 'manual') {
  subject = `[JobMatch] Thông báo kết quả ứng tuyển - ${jobTitle}`;
  body = `Xin chào ${candidateName},

Cảm ơn bạn đã quan tâm và ứng tuyển vào vị trí ${jobTitle} tại công ty chúng tôi.

Sau khi xem xét kỹ lưỡng hồ sơ, Nhà tuyển dụng đã quyết định không tiếp tục tiến trình tuyển dụng với hồ sơ của bạn ở thời điểm hiện tại.

Ghi chú từ Nhà tuyển dụng:
${reason}

Hồ sơ của bạn đã được lưu vào hệ thống dữ liệu ứng viên để chúng tôi có thể liên hệ khi có vị trí khác phù hợp hơn với định hướng của bạn.

Chúc bạn sớm tìm được công việc như ý!

Trân trọng,
Đội ngũ Tuyển dụng JobMatch VN`;
} else {
  // cv_match (sàng lọc qua hệ thống ATS)
  subject = `[JobMatch] Kết quả sàng lọc hồ sơ - ${jobTitle}`;
  body = `Xin chào ${candidateName},

Cảm ơn bạn đã quan tâm và nộp hồ sơ ứng tuyển vào vị trí ${jobTitle} tại công ty chúng tôi.

Sau khi hệ thống ATS đối soát hồ sơ của bạn với các tiêu chuẩn yêu cầu công việc${score != null ? ` (Độ phù hợp: ${score}%)` : ''}, chúng tôi nhận thấy rằng:
${reason}

Rất tiếc hồ sơ của bạn chưa thực sự tương thích với yêu cầu của vị trí này. Tuy nhiên, chúng tôi sẽ lưu hồ sơ của bạn vào talent pool và ưu tiên liên hệ khi có cơ hội phù hợp hơn.

Chúc bạn sớm tìm được công việc ưng ý!

Trân trọng,
Đội ngũ Tuyển dụng JobMatch VN`;
}

return {
  json: {
    subject,
    body,
    applicationId,
    candidateEmail,
  }
};
